package com.tamir.hamasa.data.ai

import kotlin.math.abs

/**
 * The chef's built-in recipe book: about 90 home recipes written for this app (ideas gathered from cooking sites,
 * rewritten in plain Hebrew; calories and macros calculated from an ingredient table, one portion each).
 * Built around his taste: lots of meat at lunch, cheeses / bread / eggs for breakfast and dinner, Italian and
 * Asian dishes, no fish, no seafood, no coconut, no whole tomatoes (tomato sauce is fine).
 * Every chef prompt gets a small rotating slice of it ([pick]) so the answers vary; his own book still comes first.
 *
 * Row format: name|kinds|minutes|kcal|protein|carbs|fat|grams|style|ingredient§ingredient|step§step
 * kinds: B breakfast, L lunch, D dinner, S snack.
 */
object RecipeLibrary {

    data class LibRecipe(
        val nameHe: String,
        val kinds: String,
        val minutes: Int,
        val kcal: Int,
        val proteinG: Int,
        val carbsG: Int,
        val fatG: Int,
        val grams: Int,
        val styleHe: String,
        val ingredientsHe: List<String>,
        val stepsHe: List<String>
    )

    fun kindChar(kind: MealSuggester.MealKind): Char = when (kind) {
        MealSuggester.MealKind.BREAKFAST -> 'B'
        MealSuggester.MealKind.LUNCH -> 'L'
        MealSuggester.MealKind.DINNER -> 'D'
        MealSuggester.MealKind.SNACK -> 'S'
    }

    /** Parsed once; a malformed row is skipped. */
    val all: List<LibRecipe> by lazy { ROWS.mapNotNull { parse(it) } }

    internal fun parse(row: String): LibRecipe? {
        val f = row.split('|')
        if (f.size != 11) return null
        return runCatching {
            LibRecipe(
                nameHe = f[0], kinds = f[1], minutes = f[2].toInt(), kcal = f[3].toInt(), proteinG = f[4].toInt(),
                carbsG = f[5].toInt(), fatG = f[6].toInt(), grams = f[7].toInt(), styleHe = f[8],
                ingredientsHe = f[9].split('§').filter { it.isNotBlank() },
                stepsHe = f[10].split('§').filter { it.isNotBlank() }
            )
        }.getOrNull()
    }

    /**
     * Up to [count] recipes for this meal, in a rotating order ([seed]: changes every call of the day), leaving out
     * dishes in [skip] (recently suggested, "לא בשבילי", already in his book). Recipes the chef could scale to
     * [budgetKcal] come first: at most 1.4 times the budget (dinner closes the day, so a dinner may be scaled up too).
     */
    fun pick(kind: MealSuggester.MealKind, budgetKcal: Int, skip: Collection<String>, seed: Long, count: Int = 12): List<LibRecipe> {
        val k = kindChar(kind)
        val skipSet = skip.map { it.trim() }.toSet()
        val pool = all.filter { k in it.kinds && it.nameHe !in skipSet }
        if (pool.isEmpty()) return emptyList()
        val rnd = java.util.Random(seed)
        val shuffled = pool.shuffled(rnd)
        val fits = shuffled.filter { budgetKcal <= 0 || it.kcal <= budgetKcal * 1.4f }
        val rest = shuffled.filter { it !in fits }
        return (fits + rest).take(count)
    }

    /** One prompt line: "- name (style, 650 kcal, 57 g protein, 25 min): a, b, c". */
    fun promptLine(r: LibRecipe): String =
        "- " + r.nameHe + " (" + (if (r.styleHe.isNotEmpty()) r.styleHe + ", " else "") + r.kcal + " kcal, " + r.proteinG +
            " g protein, " + r.minutes + " min): " + r.ingredientsHe.joinToString(", ")

    /** The library recipe with this name (exact, then ignoring spaces), for showing its full steps. */
    fun byName(nameHe: String): LibRecipe? {
        val n = nameHe.trim()
        return all.firstOrNull { it.nameHe == n } ?: all.firstOrNull { it.nameHe.replace(" ", "") == n.replace(" ", "") }
    }

    /** True when the kcal on the row agrees with its macros (within 15%); used by the tests. */
    internal fun consistent(r: LibRecipe): Boolean {
        val m = r.proteinG * 4 + r.carbsG * 4 + r.fatG * 9
        return m > 0 && abs(m - r.kcal) <= m * 0.15f
    }

